import{_ as o}from"./chunks/frsky_taranis_x9d_transmitter.CX5rOt5j.js";import{_ as a}from"./chunks/micronav.BCQjLXCD.js";import{_ as t,o as r,c as i,al as n}from"./chunks/framework.7vp1BMOE.js";const y=JSON.parse('{"title":"Manual Control","description":"","frontmatter":{},"headers":[],"relativePath":"zh/config/manual_control.md","filePath":"zh/config/manual_control.md"}'),s={name:"zh/config/manual_control.md"};function l(c,e,d,h,u,m){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="manual-control" tabindex="-1">Manual Control <a class="header-anchor" href="#manual-control" aria-label="Permalink to &quot;Manual Control&quot;">​</a></h1><p>Pilots can control a vehicle manually using either a <a href="./../getting_started/rc_transmitter_receiver">Radio Control (RC) System</a> or a <a href="./../config/joystick">Joystick/Gamepad</a> controller connected via QGroundControl. PX4 also supports using RC and/or multiple Joysticks, with fallback from one type to the other.</p><p><img src="'+o+'" alt="Taranis X9D Transmitter"> <img src="'+a+'" alt="Photo of MicroNav, a ground controller with integrated joysticks" width="400px"></p><h2 id="综述" tabindex="-1">综述 <a class="header-anchor" href="#综述" aria-label="Permalink to &quot;综述&quot;">​</a></h2><p><em>Joystick</em> setups use QGroundControl to encode the control information from a &quot;standard&quot; computer gaming joystick into <a href="https://mavlink.io/en/services/manual_control.html" target="_blank" rel="noreferrer">MAVLink messages</a> that are sent to the vehicle over the (shared) telemetry radio channel. They are often used in integrated GCS/manual control systems because it is cheaper and easier to integrate a joystick than a separate radio system.</p><p>Joysticks are suitable for most applications provided your telemetry channel has a high enough bandwidth/low latency. They are perfect for flying the PX4 simulator, because you can plug them directly into your ground control computer and start flying.</p><p><em>RC systems</em> use a dedicated ground-based radio transmitter and vehicle-based receiver for sending control information. They offer lower latency than Joysticks, and are very highly recommended when first tuning/testing a new frame design, when flying racers/acrobatically, and in other cases where low latency is important. They can also be useful as a robust backup link for safety. Note RC systems usually require significantly more configuration and calibration, much of which may be brand or model-specific.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 does not <em>require</em> a manual control system for autonomous flight modes.</p></div><h2 id="px4-配置" tabindex="-1">PX4 配置 <a class="header-anchor" href="#px4-配置" aria-label="Permalink to &quot;PX4 配置&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This section explains how to configure PX4 to use and prioritise various manual control sources (other configuration is covered in the guides for each type of manual control).</p></div><p>If you only have one manual control system, either RC or Joystick, then by default no manual control selection is required. In this case PX4 locks to the first valid manual control source it detects and uses that source until the vehicle is rebooted.</p><p>If you have multiple control sources, such as an RC system and/or one or more Joysticks, then you can use the <a href="./../advanced_config/parameter_reference#COM_RC_IN_MODE">COM_RC_IN_MODE</a> parameter to determine which source is active, specifying selection priorities and fallback behavior (<a href="./../advanced_config/parameters#finding-a-parameter">parameters can be set</a> using QGC):</p><ul><li><code>0</code>: RC only.</li><li><code>1</code>: MAVLink only.</li><li><code>2</code>: RC or MAVLink with fallback (switches if current source becomes invalid).</li><li><code>3</code>: RC or MAVLink keep first (locks to the first valid source until reboot).</li><li><code>4</code>: Disable manual control (ignores all sources).</li><li><code>5</code>: RC priority, then MAVLink (lower instance before higher) — <code>RC &gt; MAVLink 1 &gt; MAVLink 2</code></li><li><code>6</code>: MAVLink priority (lower instance before higher), then RC — <code>MAVLink 1 &gt; MAVLink 2 &gt; RC</code></li><li><code>7</code>: RC priority, then MAVLink (higher instance before lower) — <code>RC &gt; MAVLink 2 &gt; MAVLink 1</code></li><li><code>8</code>: MAVLink priority (higher instance before lower), then RC — <code>MAVLink 2 &gt; MAVLink 1 &gt; RC</code></li></ul><p>The <a href="./../peripherals/mavlink_peripherals#mavlink-instances">MAVLink instance</a> refers to an instance assigned to a serial port, such as <a href="./../advanced_config/parameter_reference#MAV_0_CONFIG">MAV_0_CONFIG</a>.</p><p>Notes:</p><ul><li>RC checks are run for any option that uses RC (so not for <code>MAVLink only</code> or <code>Disable manual control</code>).</li><li>When using priority sources, sources are evaluated as soon as they become valid and may trigger an immediate switch (if higher priority than the currently active source).</li><li>A <a href="./../config/safety#manual-control-loss-failsafe">Manual Control Loss Failsafe</a> is triggered when none of the manual control inputs allowed by the <code>COM_RC_IN_MODE</code> mode are available for a time that is greater than the RC Loss Timeout. As long as there is a fallback input source available, the failsafe is not triggered.</li></ul><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./../getting_started/rc_transmitter_receiver">Radio Control (RC)</a></li><li><a href="./../config/joystick">Joysticks</a></li></ul>',18)])])}const _=t(s,[["render",l]]);export{y as __pageData,_ as default};
